def is_generic_of(typ: Any, gen: Any) ->bool:
    if not is_generic(typ):
        return False
    if hasattr(typ, '__origin__'):
        return typ.__origin__ is gen
    else:
        # Handle cases where __origin__ might not be directly accessible
        # such as with certain generic types in different Python versions
        return getattr(typ, '__origin__', None) is gen
